import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Agent 可靠性与安全：让自动执行变得可控","description":"","frontmatter":{"title":"Agent 可靠性与安全：让自动执行变得可控","date":"2026-08-29T00:00:00.000Z","isComment":true,"categories":["AI","Agent"],"tags":["Agent","Security","Reliability"]},"headers":[],"relativePath":"30-agent-reliability-and-security.md","filePath":"30-agent-reliability-and-security.md","lastUpdated":1790425174000}'),n={name:"30-agent-reliability-and-security.md"};function o(s,a,r,d,p,c){return t(),l("div",null,[...a[0]||(a[0]=[i(`<h1 id="agent-可靠性与安全-让自动执行变得可控" tabindex="-1">Agent 可靠性与安全：让自动执行变得可控 <a class="header-anchor" href="#agent-可靠性与安全-让自动执行变得可控" aria-label="Permalink to &quot;Agent 可靠性与安全：让自动执行变得可控&quot;">​</a></h1><blockquote><p>Agent 的难点不是让模型多调用几个 Tool，而是让每一次调用都有边界、可恢复、可审计。</p><p><strong>边界：</strong> 本篇管运行时护栏和注入威胁模型。Tool 业务设计见 <a href="./09-tools-system-design">09</a>，上线勾选表见 <a href="./18-agent-production-checklist">18</a>。</p><p><strong>配套实验：</strong> <a href="./examples#03-可靠-agent">03 可靠 Agent</a> — 超时、重试、审批、熔断、输出截断、账本落盘、预算、dry-run、20 条注入/越权样本回归；MCP Tool 也走同一套护栏。</p></blockquote><h2 id="先区分三类系统" tabindex="-1">先区分三类系统 <a class="header-anchor" href="#先区分三类系统" aria-label="Permalink to &quot;先区分三类系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>特征</th><th>优先方案</th></tr></thead><tbody><tr><td>固定流程</td><td>步骤和分支已知</td><td>普通函数或 Workflow</td></tr><tr><td>半开放任务</td><td>有少量决策和工具</td><td>Router + 有限 Tool</td></tr><tr><td>开放任务</td><td>路径无法预先枚举</td><td>Agent，但必须有预算和审批</td></tr></tbody></table><p>能用确定性流程解决的问题，不要交给开放式 Agent。</p><h2 id="可靠性护栏" tabindex="-1">可靠性护栏 <a class="header-anchor" href="#可靠性护栏" aria-label="Permalink to &quot;可靠性护栏&quot;">​</a></h2><ul><li>每次运行有最大步骤、最大耗时和最大成本。</li><li>外部 Tool 设置超时、重试和熔断。</li><li>有副作用的 Tool 必须幂等，并支持 dry-run。</li><li>失败状态要持久化，允许从最近节点恢复。</li><li>Tool 输出限制长度，避免上下文膨胀。</li><li>并行调用要限制并发，避免触发供应商限流。</li><li>所有模型、工具和 Prompt 版本写入 Trace。</li></ul><h2 id="权限模型" tabindex="-1">权限模型 <a class="header-anchor" href="#权限模型" aria-label="Permalink to &quot;权限模型&quot;">​</a></h2><p>建议把“模型可以请求什么”和“运行时允许做什么”分成两层：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型提出 tool_call</span></span>
<span class="line"><span>  → Schema 校验</span></span>
<span class="line"><span>  → 用户/租户权限校验</span></span>
<span class="line"><span>  → 风险等级判断</span></span>
<span class="line"><span>  → 必要时人工审批</span></span>
<span class="line"><span>  → 执行并记录审计日志</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>不要把 <code>description</code> 当作权限控制。模型看到某个 Tool，不代表它应该有权调用该 Tool。</p><h2 id="prompt-injection-的正确防线" tabindex="-1">Prompt Injection 的正确防线 <a class="header-anchor" href="#prompt-injection-的正确防线" aria-label="Permalink to &quot;Prompt Injection 的正确防线&quot;">​</a></h2><p>删除 <code>ignore previous instructions</code> 等字符串不能解决注入。更可靠的策略是：</p><ol><li>将外部内容标记为不可信数据。</li><li>系统指令、用户输入、检索内容和 Tool 结果分离传递。</li><li>Tool 使用 allowlist 和最小权限。</li><li>对高风险操作要求用户确认。</li><li>用攻击样本集持续做安全回归。</li></ol><h2 id="威胁模型清单" tabindex="-1">威胁模型清单 <a class="header-anchor" href="#威胁模型清单" aria-label="Permalink to &quot;威胁模型清单&quot;">​</a></h2><ul><li>恶意用户要求泄露系统 Prompt 或密钥。</li><li>恶意网页诱导 Agent 调用危险 Tool。</li><li>文档中嵌入“忽略之前指令”的间接注入。</li><li>文件、URL、SQL 参数导致越权或 SSRF。</li><li>多租户之间发生检索、缓存或 Checkpoint 串数据。</li><li>Trace、日志和错误堆栈保存了 PII 或凭据。</li></ul><h2 id="安全-eval" tabindex="-1">安全 Eval <a class="header-anchor" href="#安全-eval" aria-label="Permalink to &quot;安全 Eval&quot;">​</a></h2><p>安全测试不能只断言“不包含 <code>sk-</code>”。应记录攻击类别、是否执行了危险 Tool、是否泄露数据、是否正确要求审批，以及拒答后的用户体验。</p><h2 id="实践任务" tabindex="-1">实践任务 <a class="header-anchor" href="#实践任务" aria-label="Permalink to &quot;实践任务&quot;">​</a></h2><ol><li>给博客助手的 Tool 分为只读、低风险写入、高风险操作三类。</li><li>为每类 Tool 增加超时、审计日志和权限检查。</li><li>建立 20 条 Prompt Injection 和越权样本，并纳入 CI。</li><li>模拟一次 Tool 失败和一次服务重启，验证任务可恢复且不会重复扣款或发信。</li></ol><h2 id="与已有内容的关系" tabindex="-1">与已有内容的关系 <a class="header-anchor" href="#与已有内容的关系" aria-label="Permalink to &quot;与已有内容的关系&quot;">​</a></h2><ul><li>Tool 设计见 <a href="./09-tools-system-design">09</a>。</li><li>生产清单见 <a href="./18-agent-production-checklist">18</a>。</li><li>LangGraph 人机协同见 <a href="./langgraph/08-human-in-the-loop">LG08</a>。</li><li>Memory 中的 PII 处理见 <a href="./13-advanced-memory">13</a>。</li></ul>`,22)])])}const b=e(n,[["render",o]]);export{u as __pageData,b as default};
